## Examples

```tsx
import { clerkClient } from '@clerk/nextjs/server'

export async function GET(req: Request) {
  // Initialize clerkClient
  const client = await clerkClient()

  // Use the `authenticateRequest()` method to verify the token
  const { isAuthenticated } = await client.authenticateRequest(req, {
    authorizedParties: ['https://example.com'],
  })

  // Protect the route from unauthenticated users
  if (!isAuthenticated) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Add logic to perform protected actions

  return Response.json({ message: 'This is a reply' })
}
```

### Machine authentication

By default, `authenticateRequest()` will authenticate a session request. To authenticate a machine request, you need to set the `acceptsToken` option to a machine token type, such as `'api_key'`, `'oauth_token'` or `'m2m_token'`.

```tsx
import { clerkClient } from '@clerk/nextjs/server'

// Initialize clerkClient
const client = await clerkClient()

export async function GET(req: Request) {
  // Use the `authenticateRequest()` method to verify the token
  const { isAuthenticated } = await client.authenticateRequest(req, {
    acceptsToken: 'oauth_token',
  })

  // Protect the route from unauthenticated users
  if (!isAuthenticated) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Add logic to perform protected actions

  return Response.json({ message: 'This is a machine-to-machine reply' })
}
```

### Networkless token verification

The following example uses the `authenticateRequest()` method with [`clerkClient`](https://clerk.com/docs/reference/backend/overview.md) to verify the token passed by the frontend, and performs a networkless authentication by passing `jwtKey`. This will verify if the user is signed into the application or not.

filename: app/api/example/route.ts
```tsx
  import { clerkClient } from '@clerk/nextjs/server'

  export async function GET(req: Request) {
    // Initialize clerkClient
    const client = await clerkClient()

    // Use the `authenticateRequest()` method to verify the token
    const { isAuthenticated } = await client.authenticateRequest(req, {
      authorizedParties: ['https://example.com'],
+     jwtKey: process.env.CLERK_JWT_KEY,
    })

    // Protect the route from unauthenticated users
    if (!isAuthenticated) {
      return Response.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Add logic to perform protected actions

    return Response.json({ message: 'This is a reply' })
  }
```

---

The following examples demonstrate how to retrieve the authenticated user's ID using framework-specific auth helpers and how to use the [`getUser()`](https://clerk.com/docs/reference/backend/user/get-user.md) method to get the [Backend `User` object](https://clerk.com/docs/reference/backend/types/backend-user.md).

For Next.js, the `Auth` object is accessed using the `auth()` helper in App Router apps and the `getAuth()` function in Pages Router apps. Learn more about [reading the Auth object in Next.js](https://clerk.com/docs/nextjs/guides/users/reading.md#server-side).

Use the following tabs to see examples of how to use these helpers to access the user's ID in your App Router or Pages Router app.

**App Router**

filename: app/api/example/route.ts
```tsx
import { auth, clerkClient } from '@clerk/nextjs/server'
import { NextResponse } from 'next/server'

export async function GET() {
  // The `Auth` object gives you access to properties like `isAuthenticated` and `userId`
  // Accessing the `Auth` object differs depending on the SDK you're using
  // https://clerk.com/docs/reference/backend/types/auth-object#how-to-access-the-auth-object
  const { isAuthenticated, userId } = await auth()

  // Protect the route by checking if the user is signed in
  if (!isAuthenticated) {
    return new NextResponse('Unauthorized', { status: 401 })
  }

  // Initialize clerkClient
  const client = await clerkClient()

  // Use the `getUser()` method to get the Backend User object
  const user = await client.users.getUser(userId)

  // Return the Backend User object
  return NextResponse.json({ user: user }, { status: 200 })
}
```

**Pages Router**

filename: pages/api/auth.ts
```tsx
import { getAuth, clerkClient } from '@clerk/nextjs/server'
import type { NextApiRequest, NextApiResponse } from 'next'

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  // Use `getAuth()` to access `isAuthenticated` and the user's ID
  const { isAuthenticated, userId } = getAuth(req)

  // Protect the route by checking if the user is signed in
  if (!isAuthenticated) {
    return res.status(401).json({ error: 'Unauthorized' })
  }

  // Initialize `clerkClient`
  const client = await clerkClient()

  // Use the `getUser()` method to get the user's full `Backend User` object
  const user = await client.users.getUser(userId)

  return res.status(200).json({ user })
}
```

## Error handling

The [`clerkClient`](https://clerk.com/docs/reference/backend/overview.md) methods throw errors ([ClerkAPIResponseError](https://clerk.com/docs/reference/types/clerk-api-response-error.md)) when something goes wrong. You'll need to catch them in a `try/catch` block and handle them gracefully. For example:

filename: example.ts
```ts
try {
  const res = await someBackendApiCall()
} catch (error) {
  // Error handling
}
```

